<script setup lang="ts">
import {ref,computed,watch,onUnmounted} from 'vue'
import Portrait from './Portrait.vue'
import CastPicker from './CastPicker.vue'
import {makeInteractionDraft,guideCandidates} from './dialogueStory'
type Row=Record<string,any>
const props=defineProps<{project:Row;history:Row[]}>()
const emit=defineEmits(['save','navigate','preview','download','check','logs','audit-export','confirm-source'])
const reviewSource=ref('')
const tab=ref('overview'),sceneId=ref(props.project.scenes[0]?.id||''),questionIndex=ref(0),reviewed=ref(false),format=ref('zip'),status=ref<Row|null>(null),checking=ref(true),error=ref(''),selectedVersion=ref<Row|null>(null)
let timer:ReturnType<typeof setTimeout>|undefined,request:AbortController|undefined,revision=0
const chapter=computed(()=>props.project.interaction?.chapters?.find((c:Row)=>c.id===sceneId.value))
const scene=computed(()=>props.project.scenes.find((s:Row)=>s.id===sceneId.value)||props.project.scenes[0])
const question=computed(()=>chapter.value?.questions[questionIndex.value]||chapter.value?.questions[0])
const guides=computed(()=>guideCandidates({...props.project,interaction:undefined}))
const errors=computed<Row[]>(()=>status.value?.issues.filter((i:Row)=>i.severity==='error')||[])
const warnings=computed<Row[]>(()=>status.value?.issues.filter((i:Row)=>i.severity==='warning')||[])
const counts=computed(()=>status.value?.counts||{characters:props.project.characters.length,scenes:props.project.scenes.length,questions:props.project.interaction?.chapters?.reduce((n:number,c:Row)=>n+c.questions.length,0)||0,guides:props.project.interaction?.guideAnnotationIds?.length||0,videos:0})
const previewReady=computed(()=>!checking.value&&!!props.project.interaction?.chapters?.length&&!errors.value.some(i=>i.code==='painting_missing'||i.section==='interaction'))
function person(cid:string){return props.project.characters.find((c:Row)=>c.id===cid)}
function box(cid:string){return props.project.annotations.find((a:Row)=>a.kind==='character'&&a.characterId===cid)}
function choose(id:string){sceneId.value=id;questionIndex.value=0}
function setup(){const draft=makeInteractionDraft(props.project),old=props.project.interaction;if(old?.chapters?.length){draft.chapters=draft.chapters.map(c=>old.chapters.find((v:Row)=>v.id===c.id)||c);draft.guideAnnotationIds=old.guideAnnotationIds.filter((id:string)=>draft.guideAnnotationIds.includes(id))}props.project.interaction=draft;tab.value='dialogue';if(!draft.chapters.some(c=>c.id===sceneId.value))choose(draft.chapters[0]?.id||'')}
function toggleGuide(id:string){const ids=props.project.interaction.guideAnnotationIds;props.project.interaction.guideAnnotationIds=ids.includes(id)?ids.filter((v:string)=>v!==id):[...ids,id]}
function addQuestion(){if(!chapter.value)return;chapter.value.questions.push({id:chapter.value.id+':'+crypto.randomUUID().slice(0,8),personId:scene.value?.characterIds[0]||props.project.characters[0]?.id||'',question:'',answer:'',clue:'',quote:'',sourceId:'',sourceVersion:1,sourceTitle:'',category:'fiction'});questionIndex.value=chapter.value.questions.length-1}
function sourceChanged(){const q=question.value;if(!q)return;const s=props.project.sources.find((s:Row)=>s.id===q.sourceId);q.sourceTitle=s?.title||'';q.sourceVersion=s?.version||1;q.quote=''}
function fix(issue:Row){if(issue.section==='interaction'){tab.value='dialogue';if(issue.sceneId)choose(issue.sceneId)}else if(issue.section==='review')tab.value='checks';else emit('navigate',issue.step,issue.sceneId)}
async function inspect(){const n=++revision;request?.abort();request=new AbortController();checking.value=true;error.value='';try{const r=await fetch('/api/projects/'+props.project.id+'/narrative/inspect',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(props.project),signal:request.signal});const value=await r.json();if(!r.ok)throw Error(typeof value.detail==='string'?value.detail:'检查暂时不可用，请重试');if(n===revision)status.value=value}catch(e){if(n===revision&&(e as Error).name!=='AbortError')error.value=String(e)}finally{if(n===revision)checking.value=false}}
watch(()=>JSON.stringify(props.project),()=>{reviewed.value=false;checking.value=true;request?.abort();revision++;if(timer)clearTimeout(timer);timer=setTimeout(inspect,500)},{immediate:true})
watch(()=>props.project.id,()=>{choose(props.project.scenes[0]?.id||'');tab.value='overview';selectedVersion.value=null})
onUnmounted(()=>{if(timer)clearTimeout(timer);request?.abort();revision++})
</script>
<template>
<section class="package-workspace">
 <div class="package-heading"><div><small>NARRATIVE PACKAGE</small><h2>让故事，完整入画</h2><p>把人物、剧本与线索连成可以阅读和交互的叙事包。</p></div><button @click="emit('save')">保存当前版本</button></div>
 <div class="package-layout"><div class="package-main"><div class="package-tabs" role="tablist" aria-label="叙事包内容"><button v-for="(label,key) in {overview:'内容总览',dialogue:'入画对话',checks:'检查与修复'}" :key="key" role="tab" :aria-selected="tab===key" :class="{active:tab===key}" @click="tab=key">{{label}}<span v-if="key==='checks'&&errors.length">{{errors.length}}</span></button></div>
 <div v-if="error" class="package-error" role="alert">{{error}} <button @click="inspect">重新检查</button></div>
 <div v-if="tab==='overview'" class="package-content"><div class="package-cover"><img v-if="project.image" :src="project.image" alt="叙事包原画"><div><small>从这幅画，开始一段体验</small><h3>{{project.paintingInfo?.name||project.title}}</h3><p>{{counts.characters}} 位人物 · {{counts.scenes}} 幕故事 · {{counts.questions}} 条问答</p><span>{{project.intent.theme||'创作主题尚未填写，可在人物与边界页补充'}}</span></div></div>
 <div class="package-section-heading"><h3>包里有什么</h3><span>内容与当前创作同步</span></div><div class="package-inventory"><button v-for="s in status?.sections||[]" :key="s.id" @click="s.id==='interaction'?tab='dialogue':s.id==='review'?tab='checks':emit('navigate',s.step,'')"><span class="inventory-mark" :class="s.status">{{s.status==='blocked'?'待':s.status==='optional'?'选':'✓'}}</span><span><b>{{s.title}}</b><small>{{s.status==='blocked'?'需要补充或核对':s.status==='optional'?'可选内容，不影响主线':'已具备'}}</small></span><span class="inventory-arrow">↗</span></button></div>
 <div class="package-section-heading"><h3>逐幕交付</h3><button @click="tab='dialogue'">编排入画对话 →</button></div><div class="package-scene" v-for="(s,i) in project.scenes" :key="s.id"><i>{{String(Number(i)+1).padStart(2,'0')}}</i><div class="package-scene-copy"><h4>{{s.title}}</h4><p>{{s.units.length}} 段剧本 · {{project.interaction?.chapters?.find((c:Row)=>c.id===s.id)?.questions.length||0}} 条问答 · {{status?.media.find((m:Row)=>m.sceneId===s.id)?.kind==='video'?'当前版动画':status?.media.find((m:Row)=>m.sceneId===s.id)?.kind==='storyboard'?'分镜呈现':'原画呈现'}}</p><div class="package-cast"><span v-for="cid in s.characterIds" :key="cid"><Portrait v-if="box(cid)&&project.image" :url="project.image" :box="box(cid)"/><small>{{person(cid)?.name||'未关联'}}</small></span></div></div><button @click="emit('navigate',3,s.id)">查看本幕 ↗</button></div><p v-if="!project.scenes.length" class="package-empty">请先建立故事大纲。</p>
 </div>
 <div v-else-if="tab==='dialogue'" class="package-content"><div class="package-section-heading dialogue-heading"><div><h3>从引路人，到一条条线索</h3><p>这里保存的内容会直接用于入画对话与导出。</p></div><button @click="setup">{{project.interaction?.chapters?.length?'同步大纲场景':'从当前体验建立草稿'}}</button></div>
 <div v-if="!project.interaction?.chapters?.length" class="package-empty"><h3>先把体验整理成可编辑的配置</h3><p>从当前演示问答与剧本建立草稿，逐幕审查后保存。此操作不会调用模型。</p><button class="primary" @click="setup">建立入画对话草稿</button></div>
 <template v-else><div class="package-guide"><h4>谁来引路</h4><p>至少选择一位已关联画作的宫人、宫女、侍女、内侍、侍从或童子。</p><div class="package-guides"><button v-for="a in guides" :key="a.id" :aria-pressed="project.interaction.guideAnnotationIds.includes(a.id)" :class="{selected:project.interaction.guideAnnotationIds.includes(a.id)}" @click="toggleGuide(a.id)"><Portrait :url="project.image" :box="a"/><span>{{person(a.characterId)?.name}}<small>{{project.interaction.guideAnnotationIds.includes(a.id)?'已选为引路人':'点击选择'}}</small></span></button></div><button v-if="!guides.length" @click="emit('navigate',0,'')">去画作探索关联引路人 ↗</button></div>
 <div class="package-chapter-tabs" role="tablist" aria-label="选择对话场景"><button v-for="(s,i) in project.scenes" :key="s.id" role="tab" :aria-selected="scene?.id===s.id" :class="{active:scene?.id===s.id}" @click="choose(s.id)">第 {{Number(i)+1}} 幕</button></div>
 <template v-if="chapter"><label>本幕体验标题<input v-model="chapter.title"></label><label>引路人开场词<textarea v-model="chapter.lead" rows="3"/></label><div class="package-question-bar"><div role="tablist" aria-label="选择问答"><button v-for="(q,i) in chapter.questions" :key="q.id" role="tab" :aria-selected="question===q" :class="{active:question===q}" @click="questionIndex=Number(i)">问答 {{Number(i)+1}}</button></div><button @click="addQuestion">＋ 添加问答</button></div>
 <div v-if="question" class="package-question"><label>由谁回答</label><CastPicker :project="project" :model-value="question.personId?[question.personId]:[]" single @update:model-value="question.personId=$event[0]||''"/><label>观众的问题<input v-model="question.question" placeholder="观众可以向人物提出什么问题？"></label><label>人物的回答<textarea v-model="question.answer" rows="4"/></label><label>读完获得的线索<input v-model="question.clue" placeholder="用一句话概括应记住的内容"></label><details class="question-evidence"><summary>回答性质与原文依据</summary><label>回答性质<select v-model="question.category"><option value="fiction">创作 / 演绎对白</option><option value="inference">解释与推测</option><option value="supported">逐字原文作答</option></select></label><label>关联来源<select v-model="question.sourceId" @change="sourceChanged"><option value="">未关联 / 创作补充</option><option v-for="s in project.sources.filter((s:Row)=>s.sourceType!=='creative_intent')" :key="s.id" :value="s.id">{{s.title}}</option></select></label><label>逐字引用<textarea v-model="question.quote" rows="3"/></label><details v-if="question.sourceId"><summary>查看当前来源全文</summary><p class="package-source">{{project.sources.find((s:Row)=>s.id===question.sourceId)?.text}}</p></details></details><button class="package-remove" @click="chapter.questions.splice(questionIndex,1);questionIndex=Math.max(0,questionIndex-1)">移除此问答</button></div><p v-else class="package-empty">本幕尚无问答，请添加至少一个。</p>
 <label>读完本幕的收束语<textarea v-model="chapter.outro" rows="2"/></label><div class="package-unlock"><small>本幕解锁路径</small><p>读完 {{chapter.questions.length}} 条问答 → 记录线索 → 解锁「{{scene?.title}}」</p><span>优先播放本场有效动画；缺少动画时，显示本场分镜或原画。</span></div><div class="package-local-actions"><button class="primary" @click="emit('save')">保存对话配置</button><button :disabled="!previewReady" @click="emit('preview')">预览当前对话草稿 ↗</button></div></template><p v-else class="package-empty">本场尚无对话配置，请点击“同步大纲场景”。已有场景的编辑会保留。</p></template>
 </div>
 <div v-else class="package-content"><div class="package-section-heading"><div><h3>先检查，再交付</h3><p>结构检查自动运行；AI 检查可作为额外建议。</p></div><button :disabled="checking" @click="inspect">{{checking?'正在检查……':'重新检查'}}</button></div><h4 class="issue-heading">需要处理 <span>{{errors.length}}</span></h4><div v-for="(issue,i) in errors" :key="i" class="package-issue"><span>!</span><div><b>{{issue.sceneId?project.scenes.find((s:Row)=>s.id===issue.sceneId)?.title:'叙事包'}}</b><p>{{issue.message}}</p><div v-if="issue.sourceId&&reviewSource===issue.sourceId" class="package-source-review"><small>{{project.sources.find((s:Row)=>s.id===issue.sourceId)?.citation}}</small><p v-if="project.sources.find((s:Row)=>s.id===issue.sourceId)?.editorialNote" class="source-adaptation">项目改编说明：{{project.sources.find((s:Row)=>s.id===issue.sourceId)?.editorialNote}}</p><p class="package-source">{{project.sources.find((s:Row)=>s.id===issue.sourceId)?.text}}</p><button class="primary" @click="emit('confirm-source',issue.sourceId)">已阅读并核对，保存来源确认</button></div></div><button @click="issue.sourceId?reviewSource=(reviewSource===issue.sourceId?'':issue.sourceId):fix(issue)">{{issue.sourceId?'展开核对':'去处理 →'}}</button></div><p v-if="!errors.length&&!checking" class="package-success">必需项目已通过结构检查。</p><details class="package-optional"><summary>可选内容与提示 · {{warnings.length}} 项</summary><p v-for="(issue,i) in warnings" :key="i">{{issue.sceneId?project.scenes.find((s:Row)=>s.id===issue.sceneId)?.title+'：':''}}{{issue.message}}</p></details><div class="package-ai-check"><h4>一致性建议 <span>可选</span></h4><p>帮助发现人物知识、历史边界与跨场景问题。生成建议后仍由你判断。</p><button @click="emit('check')">运行 AI 一致性检查</button><div v-for="c in project.checks" :key="c.id" class="package-check"><p>{{c.message}}</p><label><input type="checkbox" v-model="c.resolved"> 已处理 / 人工核查后接受</label></div></div></div>
 <details class="package-history"><summary>创作记录与版本</summary><div class="actions"><button @click="emit('logs')">载入保存历史</button><button @click="emit('audit-export','jsonl')">导出记录 JSONL</button><button @click="emit('audit-export','csv')">导出记录 CSV</button></div><div class="package-history-list"><button v-for="e in [...history].reverse()" :key="e.id" @click="selectedVersion=e">v{{e.after.version}} · {{e.action}}<small>{{new Date(e.time).toLocaleString()}}</small></button></div><details v-if="selectedVersion"><summary>查看版本 {{selectedVersion.after.version}} 的原始快照</summary><pre>{{JSON.stringify(selectedVersion.after,null,2)}}</pre></details></details>
 </div>
 <aside class="package-delivery"><small>READY FOR THE NEXT READER</small><h3>交付叙事包</h3><p>故事内容、交互规则与可用素材，放在一起。</p><div class="delivery-status" :class="{ready:status?.ready&&!checking}"><span>{{checking?'正在检查':status?.ready?'必需内容已就绪':'还有内容待完善'}}</span><b>{{checking?'…':errors.length?errors.length+' 项待处理':'✓'}}</b></div><button v-if="errors.length" class="delivery-fix" @click="tab='checks'">查看待处理项目 →</button><div class="delivery-counts"><span><b>{{counts.scenes}}</b> 幕故事</span><span><b>{{counts.questions}}</b> 条问答</span><span><b>{{counts.guides}}</b> 位引路人</span></div><label>导出形式<select v-model="format"><option value="zip">完整叙事包 ZIP（推荐）</option><option value="json">结构化内容 JSON</option><option value="md">可阅读文本 Markdown</option></select></label><p class="delivery-format-note">{{format==='zip'?'包含原画、裁切立绘、有效动画、剧本和交互配置。':format==='json'?'包含结构化内容与相对路径；素材文件需另行保留。':'便于阅读和讨论，不包含素材文件，也不能直接运行体验。'}}</p><label class="delivery-review"><input type="checkbox" v-model="reviewed" :disabled="checking||!status?.ready"> 我已审查本版问答、线索与解锁顺序</label><button class="primary deliver-final" :disabled="checking||!!error||!status?.ready||!reviewed" @click="emit('download',{format,draft:false,reviewed})">导出已确认叙事包</button><button class="deliver-draft" @click="emit('download',{format,draft:true,reviewed:false})">先导出草稿</button><button class="delivery-preview" :disabled="!previewReady" @click="emit('preview')">预览当前对话草稿 ↗</button><small class="delivery-foot">草稿保留待处理项；读者进度与创作记录单独保存，不写入体验包。</small></aside></div>
</section>
</template>
<style scoped>
